-- The Sinostech standard project plan (TemplateProjectPlan): tasks carry the plan's No., an owner written as text,
-- predecessors and percent complete, so a plan goes in and out of Excel in the same layout.
ALTER TABLE project_tasks ADD COLUMN IF NOT EXISTS owner_text text;
ALTER TABLE project_tasks ADD COLUMN IF NOT EXISTS plan_no int;
ALTER TABLE project_tasks ADD COLUMN IF NOT EXISTS pred text;
ALTER TABLE project_tasks ADD COLUMN IF NOT EXISTS pct int NOT NULL DEFAULT 0 CHECK (pct BETWEEN 0 AND 100);
